os.makedirs("logos", exist_ok=True)

def try_download(url, path):
    """Download a URL to path, return True if file is valid (>50 bytes)."""
    try:
        urllib.request.urlretrieve(url, path)
        if os.path.getsize(path) > 50:
            return True
        os.remove(path)
    except Exception:
        if os.path.exists(path):
            os.remove(path)
    return False

for ticker, domain in companies.items():
    safe = ticker.replace(".", "")
    path = f"logos/{safe}.png"
    if os.path.exists(path):
        continue

    # Try Google Favicon API first (best quality)
    url1 = f"https://t1.gstatic.com/faviconV2?client=SOCIAL&type=FAVICON&fallback_opts=TYPE,SIZE,URL&url=https://{domain}&size=128"
    if try_download(url1, path):
        time.sleep(0.1)
        continue

    # Fallback: try with www. prefix
    url2 = f"https://t1.gstatic.com/faviconV2?client=SOCIAL&type=FAVICON&fallback_opts=TYPE,SIZE,URL&url=https://www.{domain}&size=128"
    if try_download(url2, path):
        time.sleep(0.1)
        continue

    # Fallback: Google S2 favicons (different endpoint, sometimes has icons the other misses)
    url3 = f"https://www.google.com/s2/favicons?sz=128&domain={domain}"
    if try_download(url3, path):
        time.sleep(0.1)
        continue

    time.sleep(0.1)
